{% macro gallery_bar(title, summary='', class_name='') -%}
<header class="gallery-bar{% if class_name %} {{ class_name }}{% endif %}">
  <div class="gallery-bar__context"><h1 class="gallery-bar__title">{{ title }}</h1>{% if summary %}<p class="gallery-bar__summary">{{ summary }}</p>{% endif %}</div>
  <div class="gallery-bar__actions">{% if caller is defined %}{{ caller() }}{% endif %}</div>
</header>
{%- endmacro %}

